"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type DurationPrimitiveProps = ComponentProps<typeof motion.div>;

export function DurationPrimitive({ children, ...props }: DurationPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: 0}}
      animate={{x: 28}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.24, ease: [0.16, 1, 0.3, 1] }}

    >
      {children}
    </motion.div>
  );
}
